db = lancedb.connect(DB)
tbl = db.open_table('nightly-scout')
before = tbl.count_rows()

existing = set(tbl.to_pandas()['id'].tolist())
new_rows = []
for r in ROWS:
    rid = r[0]
    if rid in existing:
        continue
    new_rows.append({
        'id': rid,
        'date': DATE,
        'category': r[1],
        'title': r[2],
        'arxiv_id': r[3],
        'summary': r[4],
        'relevance': r[5],
        'tags': list(r[6]),
    })

if new_rows:
    tbl.add(new_rows)

after = tbl.count_rows()
df = tbl.to_pandas()
import collections
print('before', before, 'after', after, 'added', len(new_rows))
print('date counts:', collections.Counter(df['date']))
print('category counts for today:', collections.Counter(df[df['date'] == DATE]['category']))
# verify readback
chk = tbl.to_pandas()
today = chk[chk['date'] == DATE]
print('verified rows for', DATE, len(today))
assert len(today) == len(new_rows)
print('sample:', today.iloc[0]['id'], '|', today.iloc[0]['title'][:70])
